import{_ as a,o as e,c as i,a4 as o}from"./chunks/framework.BybBnFXO.js";const _=JSON.parse('{"title":"光学测试","description":"","frontmatter":{"title":"光学测试","identification":"optical-tests"},"headers":[],"relativePath":"zh/identification/optical-tests.md","filePath":"zh/identification/optical-tests.md","lastUpdated":1785920831000}'),r={name:"zh/identification/optical-tests.md"};function d(l,t,s,n,h,c){return e(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="光学测试" tabindex="-1">光学测试 <a class="header-anchor" href="#光学测试" aria-label="Permalink to &quot;光学测试&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>双折射（偏光镜）、多色性（二色镜）、紫外荧光（紫外灯）揭示宝石的 光学对称性与化学成分信息，是快速筛分品种与检测处理的关键。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>双折射：光在非均质宝石中分裂，值越高（如锆石 0.059）越易识别。</li><li>多色性：二色镜观察，堇青石三色性强、红宝石紫红/橙红。</li><li>紫外荧光：LW/SW 紫外灯下反应，帮助区分天然 vs 合成、产地线索。</li><li>光谱 (spectroscope)：吸收谱带是&quot;指纹&quot;，鉴定变色宝石与产地。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>zircon</td><td>DR 0.059</td><td>—</td></tr><tr><td>iolite</td><td>strong trichroism</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>',8)])])}const f=a(r,[["render",d]]);export{_ as __pageData,f as default};
